//go:build linux
// +build linux

package overlay2 // import "github.com/docker/docker/daemon/graphdriver/overlay2"

import (
	"fmt"
	"os"
	"path"
	"regexp"
	"strings"
)

// Generated by overlayutils.GenerateID(idLength): unpadded base32.
var linkIDRegexp = regexp.MustCompile(`^[A-Z2-7]{26}$`)

// diagnoseLayer reports the first malformed piece of overlay2 metadata used to
// mount id. It only reads; nothing is repaired or removed. A nil result means
// the metadata looks valid and a mount failure has some other cause.
func (d *Driver) diagnoseLayer(id string) error {
	dir := d.dir(id)
	if err := d.checkLink(id); err != nil {
		return err
	}
	lowers, err := os.ReadFile(path.Join(dir, lowerFile))
	if os.IsNotExist(err) {
		// Root layers have neither lower nor work. A child without lower
		// would silently mount as if it had no parents.
		if _, err := os.Lstat(path.Join(dir, workDirName)); err == nil {
			return fmt.Errorf("overlay2 layer %s: missing %s file for a layer with a parent", id, lowerFile)
		}
		return nil
	} else if err != nil {
		return fmt.Errorf("overlay2 layer %s: read %s: %w", id, lowerFile, err)
	}
	if len(lowers) == 0 {
		return fmt.Errorf("overlay2 layer %s: empty %s file", id, lowerFile)
	}
	for i, entry := range strings.Split(string(lowers), ":") {
		lid := strings.TrimPrefix(entry, linkDir+"/")
		if lid == entry || !linkIDRegexp.MatchString(lid) {
			return fmt.Errorf("overlay2 layer %s: invalid %s entry %d %q", id, lowerFile, i, entry)
		}
		target, err := os.Readlink(path.Join(d.home, linkDir, lid))
		if err != nil {
			return fmt.Errorf("overlay2 layer %s: %s entry %d: %w", id, lowerFile, i, err)
		}
		lowerID, ok := linkTargetLayer(target)
		if !ok {
			return fmt.Errorf("overlay2 layer %s: %s entry %d: link %s has unexpected target %q", id, lowerFile, i, lid, target)
		}
		if err := d.checkLink(lowerID); err != nil {
			return fmt.Errorf("overlay2 layer %s: %s entry %d: %w", id, lowerFile, i, err)
		}
	}
	return nil
}

// checkLink verifies id's link file and the l/ symlink that points back to it.
func (d *Driver) checkLink(id string) error {
	if _, err := os.Stat(path.Join(d.dir(id), diffDirName)); err != nil {
		return fmt.Errorf("overlay2 layer %s: %w", id, err)
	}
	link, err := os.ReadFile(path.Join(d.dir(id), "link"))
	if err != nil {
		return fmt.Errorf("overlay2 layer %s: read link: %w", id, err)
	}
	if !linkIDRegexp.Match(link) {
		return fmt.Errorf("overlay2 layer %s: invalid link file content %q", id, link)
	}
	target, err := os.Readlink(path.Join(d.home, linkDir, string(link)))
	if err != nil {
		return fmt.Errorf("overlay2 layer %s: link %s: %w", id, link, err)
	}
	if target != path.Join("..", id, diffDirName) {
		return fmt.Errorf("overlay2 layer %s: link %s points to %q", id, link, target)
	}
	return nil
}

func linkTargetLayer(target string) (string, bool) {
	parts := strings.Split(target, "/")
	if len(parts) != 3 || parts[0] != ".." || parts[2] != diffDirName || parts[1] == "" || parts[1] == "." || parts[1] == ".." {
		return "", false
	}
	return parts[1], true
}
